using System;using System.IO;using System.Collections.Generic;using System.Xml;using System.Xml.Serialization;
public class Offline70ItemReceipt {public string Id;}
public class Offline70ItemState {public int Format=1;public ushort RoleId=1;public uint ItemId=3015;public ushort Slot=105;public uint Quantity;public List<Offline70ItemReceipt> Receipts=new List<Offline70ItemReceipt>();}
class Offline70ItemDrop {internal ushort Slot;internal string Receipt;}
// One material profile on a copied diagnostic save. No production drop-table claim.
class Offline70ItemLoot {
 internal const uint ItemId=3015,TestCapacity=100;internal const ushort MaterialSlot=105;
 static readonly XmlSerializer Serializer=new XmlSerializer(typeof(Offline70ItemState));
 internal static void Validate(Offline70ItemState s){if(s==null||s.Format!=1||s.RoleId!=1||s.ItemId!=ItemId||s.Slot!=MaterialSlot||s.Quantity>TestCapacity||s.Receipts==null||s.Receipts.Count!=s.Quantity)throw new InvalidDataException("Material store profile");HashSet<string> seen=new HashSet<string>();foreach(Offline70ItemReceipt r in s.Receipts){if(r==null||r.Id==null||r.Id.Length!=37||!seen.Add(r.Id))throw new InvalidDataException("Material receipt profile");Guid id;try{id=new Guid(r.Id.Substring(0,32));}catch(FormatException){throw new InvalidDataException("Material receipt run");}if(id==Guid.Empty||r.Id[32]!='-'||String.CompareOrdinal(r.Id.Substring(33),"2000")<0||String.CompareOrdinal(r.Id.Substring(33),"2003")>0)throw new InvalidDataException("Material receipt slot");}}
 internal static Offline70ItemState Load(string path){if(!File.Exists(path))return new Offline70ItemState();if(new FileInfo(path).Length>65536)throw new InvalidDataException("Material store bounds");using(FileStream f=File.OpenRead(path))using(XmlTextReader r=new XmlTextReader(f)){r.ProhibitDtd=true;r.XmlResolver=null;Offline70ItemState s=(Offline70ItemState)Serializer.Deserialize(r);Validate(s);return s;}}
 internal static Offline70ItemState Pickup(string path,Offline70ItemDrop drop,out bool duplicate){string full=Path.GetFullPath(path);Directory.CreateDirectory(Path.GetDirectoryName(full));duplicate=false;if(drop==null||drop.Slot<2000||drop.Slot>2003||drop.Receipt==null||!drop.Receipt.EndsWith("-"+drop.Slot))throw new InvalidDataException("Unregistered material drop");using(FileStream held=new FileStream(full+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){Offline70ItemState s=Load(full);foreach(Offline70ItemReceipt r in s.Receipts)if(r.Id==drop.Receipt){duplicate=true;return s;}if(s.Quantity>=TestCapacity)throw new InvalidDataException("Diagnostic material capacity");s.Quantity++;s.Receipts.Add(new Offline70ItemReceipt{Id=drop.Receipt});Validate(s);string temp=full+".pending-"+Guid.NewGuid().ToString("N"),backup=full+".backup-"+Guid.NewGuid().ToString("N");try{using(FileStream f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){Serializer.Serialize(f,s);f.Flush();}Offline70ItemState candidate=Load(temp);if(candidate.Quantity!=s.Quantity)throw new InvalidDataException("Material readback");if(File.Exists(full))File.Replace(temp,full,backup);else File.Move(temp,full);candidate=Load(full);if(candidate.Quantity!=s.Quantity||candidate.Receipts[candidate.Receipts.Count-1].Id!=drop.Receipt)throw new InvalidDataException("Material committed readback");return candidate;}finally{if(File.Exists(temp))File.Delete(temp);}}}
 internal static Offline70ItemDrop Spawn(ushort uid,string run){if(uid<100||uid>103)throw new InvalidDataException("Material monster bounds");return new Offline70ItemDrop{Slot=(ushort)(2000+uid-100),Receipt=run+"-"+(2000+uid-100)};}
 internal static byte[] DeathBody(ushort uid,Offline70ItemDrop drop){if(drop==null||drop.Slot!=2000+uid-100)throw new InvalidDataException("Material ground profile");byte[] b=Offline70GoldLoot.DeathBody(uid,new Offline70GoldDrop{Slot=drop.Slot,Amount=18});BitConverter.GetBytes(ItemId).CopyTo(b,5);BitConverter.GetBytes((uint)1).CopyTo(b,9);return b;}
 internal static byte[] DeathReply(ushort uid,Offline70ItemDrop drop,Offline70Role role,byte[] keys){Offline70TownProtocol.Validate(role,keys);return Offline70RoleProtocol.Packet(0,38,Offline70AreaCipher.Crypt(Offline70GoldLoot.Pad(DeathBody(uid,drop),8),keys,10,true));}
 // Native49BE30 non-gold branch: slot,picker,four scores,recipient,destination,one flag.
 internal static byte[] PickupBody(ushort slot){if(slot<2000||slot>2003)throw new InvalidDataException("Material pickup slot");using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(slot);w.Write((ushort)1);w.Write(new byte[4]);w.Write((ushort)1);w.Write(MaterialSlot);w.Write((byte)0);return m.ToArray();}}
 internal static byte[] PickupReply(ushort slot,byte[] keys){return Offline70RoleProtocol.Packet(0,39,Offline70GoldCipher.Crypt(Offline70GoldLoot.Pad(Offline70RoleProtocol.WithDungeonIntegrity(PickupBody(slot)),8),keys,11,true));}
 internal static byte[] RestoreBody(uint gold,Offline70ItemState s){Validate(s);byte[] original=Offline70QuestFinish.GoldRestoreBody(gold);if(s.Quantity==0)return original;byte[] b=new byte[original.Length+31];original.CopyTo(b,0);BitConverter.GetBytes((ushort)2).CopyTo(b,3);byte[] row=Offline70QuestFinish.GoldBody(0);Array.Copy(row,3,b,original.Length,31);BitConverter.GetBytes(MaterialSlot).CopyTo(b,original.Length);BitConverter.GetBytes(ItemId).CopyTo(b,original.Length+2);BitConverter.GetBytes(s.Quantity).CopyTo(b,original.Length+6);return b;}
 internal static byte[] RestoreReply(byte[] keys,uint gold,Offline70ItemState s){return Offline70RoleProtocol.Packet(0,13,Offline70GoldCipher.Crypt(Offline70GoldLoot.Pad(RestoreBody(gold,s),16),keys,13,true));}
}
